const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export function resendPanel(order,api,onSent){const box=el('section'),tools=el('div'),review=el('div'),feedback=el('p');box.className='order-resend';tools.className='resend-tools';feedback.setAttribute('role','status');box.append(el('h3','Send dokumenter og ordreinfo'),el('p','Gennemse modtager, besked og bilag før afsendelse. Der oprettes ingen ny ordre, faktura eller betaling.'),tools,feedback,review);let generation=0;
async function preview(action,button){const current=++generation;review.replaceChildren();feedback.textContent='Henter forhåndsvisning…';button.disabled=true;try{const d=await(await api(`/api/pf-orders/${order.id}/resend`,'POST',{action})).json();if(current!==generation)return;feedback.textContent='';review.append(el('h3','Gennemse før afsendelse'),el('p','Til: '+d.to),el('strong',d.subject),el('pre',d.text));for(const a of d.attachments){const link=el('a','Åbn bilag: '+a.name);link.href=`/api/pf-orders/${order.id}/resend/${d.id}/attachment/${a.index}`;link.target='_blank';link.rel='noopener';review.append(link);}if(!d.attachments.length)review.append(el('small','Ingen vedhæftede bilag.'));const send=el('button','Send til '+d.to),cancel=el('button','Luk forhåndsvisning');send.type=cancel.type='button';cancel.onclick=()=>{generation++;review.replaceChildren();};send.onclick=async()=>{send.disabled=true;cancel.disabled=true;try{const result=await(await api(`/api/pf-orders/${order.id}/resend`,'POST',{draftId:d.id})).json();feedback.textContent=result.status==='sent'?'Mailen er accepteret af mailserveren.':result.error||'Afsendelsen er ikke bekræftet. Kontrollér historikken.';review.replaceChildren();await onSent();}catch(e){feedback.textContent=e.message;await onSent();cancel.disabled=false;}};review.append(send,cancel);}catch(e){feedback.textContent=e.message;}finally{button.disabled=false;}}
api(`/api/pf-orders/${order.id}/resend`).then(r=>r.json()).then(options=>{for(const o of options){const wrap=el('div'),button=el('button',o.label);button.type='button';button.disabled=!o.available;button.onclick=()=>preview(o.action,button);wrap.append(button);if(o.reason)wrap.append(el('small',o.reason));tools.append(wrap);}}).catch(e=>{feedback.textContent='Handlingerne kunne ikke indlæses: '+e.message;});return box;}
